import numpy as np

def select_next_node(cur_truck_pos, depot_pos, all_truck_pos, unvisited_customers):
    # Novel algorithm: Average Truck Distance Differential (ATDD)
    # Description: {The algorithm selects the unvisited customer that minimizes the difference between its distance to the current truck and the average distance to all other trucks, only moving if such difference is negative, otherwise waiting.}

    if not unvisited_customers:
        return None

    cur = np.array(cur_truck_pos)
    others = [np.array(pos) for pos in all_truck_pos if not np.array_equal(pos, cur_truck_pos)]

    best_node = None
    best_score = float('inf')

    for i, cust in enumerate(unvisited_customers):
        cust = np.array(cust)
        dist_cur = np.linalg.norm(cust - cur)
        if others:
            avg_other = np.mean([np.linalg.norm(cust - o) for o in others])
        else:
            avg_other = float('inf')
        score = dist_cur - avg_other
        if score < best_score:
            best_score = score
            best_node = i

    # Only move if current truck is strictly closer (on average) than other trucks
    if best_score >= 0:
        return None  # wait
    else:
        return best_node
